:root {
  --card-bg: #ffffff;
  --header-bg: #c0392b;
  --header-text: #ffffff;
  --subtitle-text: #fddbd9;
  --stamp-filled-bg: #c0392b;
  --stamp-filled-border: #922b21;
  --stamp-empty-bg: #f9f0f0;
  --stamp-empty-border: #e8c8c8;
  --footer-bg: #fdf4f4;
  --footer-border: #f0d8d8;
  --member-label-color: #a04040;
  --member-name-color: #2c2c2c;
  --reward-bg: #c0392b;
  --reward-text: #ffffff;
  --card-border: #e0c0c0;
}

.loyalty-card {
  background: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 16px;
  width: 420px;
  overflow: hidden;
  font-size: 14px;
}

.card-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
}

.card-icon {
  font-size: 32px;
  line-height: 1;
}

.card-title h2 {
  font-size: 18px;
  font-weight: 700;
  color: var(--header-text);
  margin: 0 0 2px 0;
}

.card-subtitle {
  font-size: 12px;
  color: var(--subtitle-text);
  margin: 0;
}

.stamps {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 8px;
  padding: 18px 16px;
}

.stamp {
  aspect-ratio: 1;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  border: 2px solid var(--stamp-empty-border);
  background: var(--stamp-empty-bg);
}

.stamp.filled {
  background: var(--stamp-filled-bg);
  border-color: var(--stamp-filled-border);
}

.card-footer {
  background: var(--footer-bg);
  border-top: 1px solid var(--footer-border);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
}

.member-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--member-label-color);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.member-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--member-name-color);
  flex: 1;
}

.reward-badge {
  background: var(--reward-bg);
  color: var(--reward-text);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}
